    /// <summary>
    /// Changes the emoji status of the current user; for Telegram Premium users only
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetEmojiStatusAsync(EmojiStatus emojiStatus = default)
    {

           using var activity =  StartCallActivity("SetEmojiStatusAsync", typeof(SetEmojiStatus).FullName ?? "SetEmojiStatusAsync");

           try
           {
             return client.SetEmojiStatusAsync(emojiStatus);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
